import {join} from 'node:path';
import {mongoDownloadDirectory} from './mongoTestSupport.js';

describe('MongoDB test binary downloads', () => {
  it('isolates download locks for processes sharing a cache', () => {
    const cache = join('cache', 'mongodb');

    expect([mongoDownloadDirectory(cache, 101), mongoDownloadDirectory(cache, 202)]).toEqual([
      join(cache, '101'),
      join(cache, '202'),
    ]);
  });
});
